\set A '00000000-0000-0000-0000-00000000000a'
\set B '00000000-0000-0000-0000-00000000000b'
\set C '00000000-0000-0000-0000-00000000000c'
select set_config('t.uid', :'B', false);
select '1 h2h odd', create_contest_league('X','high','h2h','season',5) ->> 'error';
select '2 h2h', (create_contest_league('H2H High','high','h2h','season',4, 40000)) - 'invite_code' - 'league_id';
create temp table H as select id, invite_code from league where name='H2H High';
select '3 seats', count(*), count(app_user_id) from league_membership where league_id=(select id from H);
select '4 golf board', (create_contest_league('Golf','golf','board','season',12, 50000)) -> 'bullseye';
create temp table G as select id, invite_code from league where name='Golf';
select '5 settings golf', settings_json -> 'golf', settings_json ->> 'contest', settings_json ->> 'game_mode' from league where id=(select id from G);
select '6 bull', (create_contest_league('Bull','bullseye','board','week',3, 50000, 'total', 8)) -> 'bullseye' ->> 'contest';
select set_config('t.uid', :'C', false);
select '7 join h2h', join_contest((select invite_code from H), 'Eve') - 'league_id';
select '8 join golf', join_contest((select invite_code from G)) ->> 'roster_id';
select '9 ok', save_contest_entry((select id from H), 6, '{"S1":"hurts","S2":"barkley","S3":"hall","S4":"lamb","S5":"brown","S6":"kelce-wr","S7":"kittle","S8":"phi-k","S9":"sf-dst"}') - 'roster_id';
select '10 wrong pos', save_contest_entry((select id from H), 6, '{"S1":"barkley","S2":"hurts","S3":"hall","S4":"lamb","S5":"brown","S6":"kelce-wr","S7":"kittle","S8":"phi-k","S9":"sf-dst"}') ->> 'error';
select '11 dup', save_contest_entry((select id from H), 6, '{"S1":"hurts","S2":"barkley","S3":"barkley","S4":"lamb","S5":"brown","S6":"kelce-wr","S7":"kittle","S8":"phi-k","S9":"sf-dst"}') ->> 'error';
select '12 missing', save_contest_entry((select id from H), 6, '{"S1":"hurts"}') ->> 'error';
select '13 budget', save_contest_entry((select id from H), 6, '{"S1":"allen","S2":"mccaffrey","S3":"barkley","S4":"lamb","S5":"brown","S6":"wilson","S7":"kittle","S8":"phi-k","S9":"sf-dst"}') ->> 'error';
select set_config('t.uid', :'B', false);
update league set settings_json = settings_json || '{"roster_slots":[{"pos":["QB"]},{"pos":["RB"]},{"pos":["RB"],"max_exp":2,"label":"Young RB"},{"pos":["WR"]},{"pos":["WR","TE"]},{"pos":["RB","WR","TE"]},{"pos":["K"]},{"pos":["DEF"]}]}'::jsonb where id=(select id from G);
select '14 golf flex ok', save_contest_entry((select id from G), 6, '{"S1":"hurts","S2":"barkley","S3":"hall","S4":"lamb","S5":"kittle","S6":"brown","S7":"phi-k","S8":"sf-dst"}') ->> 'ok';
select '15 tenure', save_contest_entry((select id from G), 6, '{"S1":"hurts","S2":"hall","S3":"barkley","S4":"lamb","S5":"kittle","S6":"brown","S7":"phi-k","S8":"sf-dst"}') ->> 'error';
select '16 flex pos', save_contest_entry((select id from G), 6, '{"S1":"hurts","S2":"barkley","S3":"hall","S4":"lamb","S5":"brown","S6":"hurts","S7":"phi-k","S8":"sf-dst"}') ->> 'error';
update league set settings_json = settings_json || '{"pool_filter":{"teams":["PHI","SF","NYJ"]}}'::jsonb where id=(select id from G);
select '17 pool filter', save_contest_entry((select id from G), 6, '{"S1":"hurts","S2":"barkley","S3":"hall","S4":"lamb","S5":"kittle","S6":"brown","S7":"phi-k","S8":"sf-dst"}') ->> 'error';
update league set settings_json = settings_json - 'pool_filter' where id=(select id from G);
insert into seat_player_rule (league_id, roster_id, positions, teams) values ((select id from G), 1, null, array['PHI']);
select '18 seat rule', save_contest_entry((select id from G), 6, '{"S1":"hurts","S2":"barkley","S3":"hall","S4":"lamb","S5":"kittle","S6":"brown","S7":"phi-k","S8":"sf-dst"}') ->> 'error';
delete from seat_player_rule;
update league set settings_json = jsonb_set(settings_json, '{roster_slots,0,flags}', '["Franchise"]') where id=(select id from G);
select '19 flag', save_contest_entry((select id from G), 6, '{"S1":"hurts","S2":"barkley","S3":"hall","S4":"lamb","S5":"kittle","S6":"brown","S7":"phi-k","S8":"sf-dst"}') ->> 'error';
insert into player_flag values ((select id from G), 'hurts', 'franchise');
select '20 flag ok', save_contest_entry((select id from G), 6, '{"S1":"hurts","S2":"barkley","S3":"hall","S4":"lamb","S5":"kittle","S6":"brown","S7":"phi-k","S8":"sf-dst"}') ->> 'ok';
select '21 board row', count(*) from matchup where league_id=(select id from G);
select '22 state', (contest_state((select id from G))) -> 'slots' -> 2, (contest_state((select id from G))) ->> 'contest', (contest_state((select id from G))) ->> 'budget';
select '23 rules', set_contest_rules((select id from H), 'golf', null, 30000) -> 'bullseye' ->> 'contest';
select '23b golf set', settings_json -> 'golf', settings_json ->> 'budget' from league where id=(select id from H);
select '24 format locked', set_contest_rules((select id from G), null, 'h2h', null) ->> 'error';
select '25 bull switch', set_contest_rules((select id from H), 'bullseye', null, null) -> 'bullseye' ->> 'contest';
select '25b', settings_json ->> 'dfs_bullseye', settings_json -> 'golf' from league where id=(select id from H);
select '26 size grow', set_bullseye_size((select id from H), 6) ->> 'ok';
select '26b', count(*) from league_membership where league_id=(select id from H);
select '27 size shrink taken', set_bullseye_size((select id from H), 2) ->> 'error';
select '28 seats open h2h', _league_seats_open((select id from H)), 'board', _league_seats_open((select id from G));
update matchup set status='final', home_final=20, away_final=20 where league_id=(select id from G);
select set_config('t.uid', :'C', false);
select '29 golf board', contest_board((select id from G)) -> 'rows' -> 0 ->> 'team_name', contest_board((select id from G)) ->> 'contest';
select '30 my weeks', bullseye_my_weeks((select id from G)) -> 'weeks' -> 0 ->> 'rank';
select '31 old bullseye rpc', bullseye_league((select id from G)) -> 'bullseye' ->> 'format';
select '32 join dfs legacy', join_dfs((select invite_code from H)) ->> 'already';
select set_config('t.uid', :'B', false);
select '33 post', post_league_listing((select id from H), 'come', null) ->> 'ok';
select '34 board listing', jsonb_path_query_array(league_board(), '$[*].bullseye.contest');
